            display: flex;
            justify-content: space-around;
            align-items: center;
            list-style: none;
            margin: 0;
            padding: 5px 0;
        }

        .ios-tab-bar a {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-decoration: none;
            color: var(--ios-gray);
            font-size: 10px;
            font-weight: 500;
            padding: 5px;
            min-width: 65px;
            position: relative;
            transition: color 0.2s ease-in-out;
        }

        .ios-tab-bar a.active {
            color: var(--ios-blue);
        }

        .ios-tab-bar i {
            font-size: 24px;
            margin-bottom: 4px;
            display: block;
        }

        .tab-slider {
            position: absolute;
            bottom: 0;
            height: 2px;
            background-color: var(--ios-blue);
            border-radius: 2px;
